import {usd} from '@/lib/pilot';
import {taxLabels,type ChargeBreakdown as Breakdown} from '@/lib/rates';
export function ChargeBreakdown({value}:{value:Breakdown}){
 return <div className="pilot-charge-breakdown"><h3>Taxes &amp; fees breakdown</h3>{value.mode==='adjusted'&&<p>Amounts were adjusted after booking. Hotel fees retain their booked amounts; review them when stay dates change.</p>}<dl><div><dt>Room charges</dt><dd>{usd(value.accommodation_minor)}</dd></div>{value.fees.map(line=><div key={line.code}><dt>{line.label}<small>{usd(line.unit_amount_minor)} {line.basis==='per_night'?'per night':'per stay'} × {line.quantity}{line.taxes.length>0?' · Taxable under '+line.taxes.map(t=>taxLabels[t]).join(', '):' · No fee taxes selected'}</small></dt><dd>{usd(line.amount_minor)}</dd></div>)}{value.taxes.map(line=><div key={line.code}><dt>{line.label}<small>{line.basis_points!==null?(line.basis_points/100).toFixed(2)+'%':''}{line.taxable_base_minor!==null?' on '+usd(line.taxable_base_minor):''}</small></dt><dd>{usd(line.amount_minor)}</dd></div>)}{value.ota_fees_minor>0&&<div><dt>OTA fees</dt><dd>{usd(value.ota_fees_minor)}</dd></div>}<div className="pilot-charge-total"><dt>Total stay value</dt><dd>{usd(value.total_minor)}</dd></div></dl></div>;
}
